package com.dexm.personajes.adapter.out.persistence;
public class CharacterMinorAttributeValueEntity { private String id; private String characterId; private String definitionId; private int value; protected CharacterMinorAttributeValueEntity(){} public CharacterMinorAttributeValueEntity(String id,String characterId,String definitionId,int value){this.id=id;this.characterId=characterId;this.definitionId=definitionId;this.value=value;} public String getId(){return id;} public String getCharacterId(){return characterId;} public String getDefinitionId(){return definitionId;} public int getValue(){return value;} public void setValue(int v){value=v;} }
